public class MothershipHttpClientUnity : MothershipSendHTTPRequestDelegateWrapper
{
	private MothershipClientApiClient client;

	private bool isRequestLoggingEnabled;

	public MothershipHttpClientUnity(MothershipClientApiClient client, bool isRequestLoggingEnabled)
	{
		swigCMemOwn = false;
		this.client = client;
		this.isRequestLoggingEnabled = isRequestLoggingEnabled;
	}

	public override bool SendRequest(MothershipHTTPRequest request)
	{
		UnityWebRequest unityWebRequest = new UnityWebRequest(request.Path, request.Verb.ToString());
		byte[] data = null;
		if (request.Verb == MothershipHTTPVerbs.POST)
		{
			data = new UTF8Encoding().GetBytes(request.Body);
		}
		if (isRequestLoggingEnabled)
		{
			UnityEngine.Debug.Log($"Mothership request body: {request.Body}");
		}
		unityWebRequest.uploadHandler = new UploadHandlerRaw(data);
		unityWebRequest.downloadHandler = new DownloadHandlerBuffer();
		foreach (MothershipHttpHeader requestHeader in request.RequestHeaders)
		{
			if (isRequestLoggingEnabled)
			{
				UnityEngine.Debug.Log($"Mothership request header: {requestHeader.Name} {requestHeader.Value})");
			}
			unityWebRequest.SetRequestHeader(requestHeader.Name, requestHeader.Value);
		}
		unityWebRequest.timeout = 5;
		MothershipHttpRunner.instance.SendRequest(unityWebRequest, request, delegate(MothershipHTTPResponse Response)
		{
			if (isRequestLoggingEnabled)
			{
				UnityEngine.Debug.Log($"Mothership: Request to {request.Path} status {Response.statusCode}");
			}
			client.ReceiveHttpResponse(Response);
		});
		return true;
	}
}
public class MothershipHttpRunner : MonoBehaviour
{
	private static MothershipHttpRunner _instance;

	public static MothershipHttpRunner instance
	{
		get
		{
			CreateInstance();
			return _instance;
		}
	}

	private static void CreateInstance()
	{
		if (_instance == null)
		{
			_instance = new GameObject(typeof(MothershipHttpRunner).Name).AddComponent<MothershipHttpRunner>();
		}
	}

	public virtual void Awake()
	{
		if (Application.isPlaying)
		{
			UnityEngine.Object.DontDestroyOnLoad(this);
		}
		if (_instance != null)
		{
			_instance = null;
			UnityEngine.Object.DestroyImmediate(base.gameObject);
		}
	}

	public void SendRequest(UnityWebRequest uwr, MothershipHTTPRequest request, Action<MothershipHTTPResponse> responseCallback)
	{
		StartCoroutine(SendRequestInternal(uwr, request, responseCallback));
	}

	private IEnumerator SendRequestInternal(UnityWebRequest uwr, MothershipHTTPRequest request, Action<MothershipHTTPResponse> responseCallback)
	{
		yield return uwr.SendWebRequest();
		MothershipHTTPResponse mothershipHTTPResponse = new MothershipHTTPResponse();
		mothershipHTTPResponse.statusCode = (int)uwr.responseCode;
		mothershipHTTPResponse.Body = uwr.downloadHandler.text;
		mothershipHTTPResponse.cbData = request.cbData;
		responseCallback(mothershipHTTPResponse);
	}
}
