public class MothershipWebSocketDispatcher : MonoBehaviour
{
	private static MothershipWebSocketDispatcher _instance;

	private static bool _isApplicationQuitting;

	public static MothershipWebSocketDispatcher instance
	{
		get
		{
			if (_instance == null)
			{
				_instance = UnityEngine.Object.FindFirstObjectByType<MothershipWebSocketDispatcher>();
				if (_instance == null)
				{
					_instance = new GameObject("MothershipWebSocketDispatcher").AddComponent<MothershipWebSocketDispatcher>();
				}
			}
			return _instance;
		}
	}

	public void Awake()
	{
		if (_instance != null && _instance != this)
		{
			UnityEngine.Debug.LogWarning("WebSocket: Duplicate MothershipWebSocketDispatcher found. Destroying.");
			UnityEngine.Object.DestroyImmediate(base.gameObject);
		}
		else
		{
			_instance = this;
			UnityEngine.Object.DontDestroyOnLoad(base.gameObject);
		}
	}

	public void Update()
	{
		if (!_isApplicationQuitting)
		{
			MothershipClientApiUnity.TickWebSockets(Time.deltaTime);
		}
	}

	private void OnApplicationQuit()
	{
		_isApplicationQuitting = true;
		MothershipClientApiUnity.CloseWebSockets();
	}

	private void OnDestroy()
	{
		if (_instance == this)
		{
			MothershipClientApiUnity.CloseWebSockets();
			_instance = null;
		}
	}
}
internal class MothershipWebSocketRetryQueue
{
	private class RetryingWebSocket : IEquatable<ActiveWebSocket>
	{
		private readonly ActiveWebSocket _websocket;

		private float _lastSetTime = 5f;

		private float _timeLeft = 5f;

		private bool _retryEnabled;

		public RetryingWebSocket(ActiveWebSocket socket)
		{
			_websocket = socket;
		}

		public void Retry()
		{
			_retryEnabled = true;
		}

		public void Reset()
		{
			_timeLeft = 5f;
			_lastSetTime = _timeLeft;
		}

		public void Tick(float deltaSeconds)
		{
			if (_retryEnabled)
			{
				_timeLeft -= deltaSeconds;
				if (!(_timeLeft > 0f))
				{
					_timeLeft = MathF.Min(_lastSetTime * 2f, 120f);
					_lastSetTime = _timeLeft;
					_retryEnabled = false;
					_websocket.resetSocket?.Invoke(_websocket.requestData);
				}
			}
		}

		public bool Equals(ActiveWebSocket other)
		{
			return _websocket == other;
		}
	}

	private const float MAX_RETRY_SECONDS = 120f;

	private const float INITIAL_RETRY_SECONDS = 5f;

	private readonly List<RetryingWebSocket> _websockets = new List<RetryingWebSocket>();

	public void AddSocket(ActiveWebSocket socket)
	{
		if (GetRetryingSocket(socket) == null)
		{
			_websockets.Add(new RetryingWebSocket(socket));
		}
	}

	public void RemoveSocket(ActiveWebSocket socket)
	{
		for (int i = 0; i < _websockets.Count; i++)
		{
			if (_websockets[i].Equals(socket))
			{
				_websockets.RemoveAt(i);
				break;
			}
		}
	}

	public void ClearSockets()
	{
		_websockets.Clear();
	}

	public void RetrySocket(ActiveWebSocket socket)
	{
		GetRetryingSocket(socket)?.Retry();
	}

	public void ResetSocket(ActiveWebSocket socket)
	{
		GetRetryingSocket(socket)?.Reset();
	}

	public void Tick(float deltaSeconds)
	{
		foreach (RetryingWebSocket websocket in _websockets)
		{
			websocket.Tick(deltaSeconds);
		}
	}

	private RetryingWebSocket GetRetryingSocket(ActiveWebSocket socket)
	{
		foreach (RetryingWebSocket websocket in _websockets)
		{
			if (websocket.Equals(socket))
			{
				return websocket;
			}
		}
		return null;
	}
}
public class MothershipWebSocketWrapper : MothershipWebSocketDelegateWrapper
{
	private readonly MothershipClientApiClient _client;

	private readonly MothershipWebSocketRetryQueue _retryQueue;

	private readonly List<ActiveWebSocket> _websockets;

	public MothershipWebSocketWrapper(MothershipClientApiClient client)
	{
		swigCMemOwn = false;
		_client = client;
		_retryQueue = new MothershipWebSocketRetryQueue();
		_websockets = new List<ActiveWebSocket>();
	}

	public void RefreshClientTokenHeaders()
	{
		foreach (ActiveWebSocket websocket in _websockets)
		{
			websocket.websocket.SetRequestHeader(MothershipApi.MOTHERSHIP_CLIENT_TOKEN_HEADER, MothershipClientContext.Token);
			foreach (MothershipHttpHeader requestHeader in websocket.requestData.RequestHeaders)
			{
				if (requestHeader.Name == MothershipApi.MOTHERSHIP_CLIENT_TOKEN_HEADER)
				{
					requestHeader.Value = MothershipClientContext.Token;
					break;
				}
			}
		}
	}

	public void TickWebSockets(float deltaTime)
	{
		foreach (ActiveWebSocket websocket in _websockets)
		{
			if (websocket.websocket.State == WebSocketState.Open)
			{
				websocket.websocket.DispatchMessageQueue();
			}
		}
		_retryQueue.Tick(deltaTime);
	}

	public override bool CreateConnection(MothershipOpenWebSocketEventArgs request)
	{
		ActiveWebSocket activeWebSocket = _websockets.Find((ActiveWebSocket ws) => ws.requestData.Path == request.Path);
		if (activeWebSocket != null)
		{
			activeWebSocket.resetSocket?.Invoke(request);
			return true;
		}
		ActiveWebSocket aws = new ActiveWebSocket();
		CreateSocket(request);
		return true;
		void CreateSocket(MothershipOpenWebSocketEventArgs req)
		{
			Dictionary<string, string> dictionary = new Dictionary<string, string>();
			foreach (MothershipHttpHeader requestHeader in req.RequestHeaders)
			{
				dictionary.Add(requestHeader.Name, requestHeader.Value);
			}
			WebSocket webSocket = new WebSocket(req.Path, dictionary);
			aws.requestData = req;
			aws.resetSocket = CreateSocket;
			aws.websocket = webSocket;
			webSocket.OnOpen += OnOpen;
			webSocket.OnMessage += OnMessage;
			webSocket.OnClose += OnClose;
			webSocket.OnError += OnError;
			webSocket.Connect();
		}
		void OnClose(WebSocketCloseCode code)
		{
			if (code > WebSocketCloseCode.Normal)
			{
				UnityEngine.Debug.Log($"WebSocket retrying due to close code: {code}");
				_retryQueue.RetrySocket(aws);
			}
			else
			{
				MothershipWebSocketResponse response = new MothershipWebSocketResponse
				{
					Event = MothershipWebSocketEvents.CLOSE,
					cbData = aws.requestData.cbData
				};
				_client.ReceiveWebsocketMessage(response);
				_retryQueue.RemoveSocket(aws);
				_websockets.Remove(aws);
			}
		}
		static void OnError(string error)
		{
			UnityEngine.Debug.LogError("WebSocket erroring: " + error);
		}
		void OnMessage(byte[] data)
		{
			try
			{
				string message = Encoding.UTF8.GetString(data);
				MothershipWebSocketResponse response = new MothershipWebSocketResponse
				{
					Event = MothershipWebSocketEvents.MESSAGE,
					Message = message,
					cbData = aws.requestData.cbData
				};
				_client.ReceiveWebsocketMessage(response);
			}
			catch (Exception arg)
			{
				UnityEngine.Debug.LogError($"WebSocket exception in onMessage: {arg}");
			}
		}
		void OnOpen()
		{
			try
			{
				if (!_websockets.Contains(aws))
				{
					_websockets.Add(aws);
					_retryQueue.AddSocket(aws);
				}
				else
				{
					_retryQueue.ResetSocket(aws);
				}
				MothershipWebSocketResponse response = new MothershipWebSocketResponse
				{
					Event = MothershipWebSocketEvents.OPEN,
					cbData = aws.requestData.cbData
				};
				_client.ReceiveWebsocketMessage(response);
			}
			catch (Exception arg)
			{
				UnityEngine.Debug.LogError($"WebSocket exception in OnOpen: {arg}");
			}
		}
	}

	public override bool CloseConnection(MothershipCloseWebSocketEventArgs request)
	{
		for (int i = 0; i < _websockets.Count; i++)
		{
			ActiveWebSocket activeWebSocket = _websockets[i];
			if (!(request.Path != activeWebSocket.requestData.Path))
			{
				try
				{
					activeWebSocket.websocket.Close();
				}
				catch
				{
					UnityEngine.Debug.LogError("WebSocket " + request.Path + " failed to close");
				}
				_retryQueue.RemoveSocket(activeWebSocket);
				_websockets.RemoveAt(i);
				return true;
			}
		}
		return false;
	}

	public void CloseConnections()
	{
		Task.Run((Func<Task>)CloseConnectionsAsync).GetAwaiter().GetResult();
	}

	private async Task CloseConnectionsAsync()
	{
		foreach (ActiveWebSocket websocket in _websockets)
		{
			try
			{
				MothershipWebSocketResponse response = new MothershipWebSocketResponse
				{
					Event = MothershipWebSocketEvents.CLOSE,
					cbData = websocket.requestData.cbData
				};
				_client.ReceiveWebsocketMessage(response);
				await websocket.websocket.Close();
			}
			catch
			{
				UnityEngine.Debug.LogError("WebSockets failed to close");
			}
		}
		_websockets.Clear();
		_retryQueue.ClearSockets();
	}
}
internal class ActiveWebSocket
{
	public WebSocket websocket;

	public MothershipOpenWebSocketEventArgs requestData;

	public Action<MothershipOpenWebSocketEventArgs> resetSocket;
}
